import { atom, read, update } from 'claude-code'
import type { Hook, Register, SessionContextUsage, SessionRateLimit } from 'claude-code'

import type { UsageReading } from '../types'

type Engine = Parameters<Hook<'session.measure'>>[0]

const reading = atom({ plugin: 'usage-band', key: 'reading' } as const, null)

// A figure turns to the warning colour at this much.
const PLAN_WARN_PERCENT = 80
const CONTEXT_WARN_PERCENT = 90

// Re-reads the plan usage file each minute, so the plan figures stay current between turns.
const REFRESH_MS = 60000

const SESSION_WINDOW = 'five_hour'
const WEEKLY_WINDOW = 'seven_day'

// Where the desktop app records plan usage samples: { samples: [{ t, u: { fh, sd } }] }, fh the 5-hour and sd the 7-day window.
const PLAN_USAGE_FILE = 'Claude/plan-usage-history.json'
const MAC_APP_SUPPORT = 'Library/Application Support'

type PlanUsage = { sessionPercent?: number; weeklyPercent?: number }

// The token count at which auto-compaction runs, for the window it was measured against; only a new window size changes it.
let compaction: { window: number; thresholdTokens?: number } | null = null

// Whether the last measurement carried live plan figures; while it did, the plan usage file is not needed.
let hasLivePlanUsage = false

async function compactionThreshold($: Engine, context: SessionContextUsage) {
  if (compaction?.window !== context.window) {
    try {
      // A summary breakdown is estimated locally, so this sends no request.
      const { breakdown } = (await $.session.usage({ breakdown: 'summary' })).context
      compaction = {
        window: context.window,
        thresholdTokens: breakdown?.isAutoCompactEnabled ? breakdown.autoCompactThreshold : undefined,
      }
    } catch {
      // Without the threshold the band measures against the whole window; the next measurement tries again.
      return undefined
    }
  }

  return compaction.thresholdTokens
}

// The context's progress towards auto-compaction; against the whole window when there is no threshold.
async function contextPercent($: Engine, context: SessionContextUsage) {
  const threshold = await compactionThreshold($, context)
  if (context.tokens === undefined || threshold === undefined) {
    return context.percent
  }

  return Math.round((context.tokens / threshold) * 100)
}

// The plan usage file's newest sample; empty when there is no file or it cannot be read.
async function planUsageFromFile($: Engine): Promise<PlanUsage> {
  try {
    const appData = await $.env.get('APPDATA')
    const home = await $.env.get('HOME')
    const folder = appData ?? (home === undefined ? undefined : `${home}/${MAC_APP_SUPPORT}`)
    if (folder === undefined) {
      return {}
    }

    const history = JSON.parse(await $.fs.read(`${folder}/${PLAN_USAGE_FILE}`)) as { samples?: { u?: { fh?: unknown; sd?: unknown } }[] }
    const newest = history.samples?.at(-1)?.u

    return {
      sessionPercent: typeof newest?.fh === 'number' ? newest.fh : undefined,
      weeklyPercent: typeof newest?.sd === 'number' ? newest.sd : undefined,
    }
  } catch {
    return {}
  }
}

// Live figures when the engine passes them on, which the desktop app does not always do; the plan usage file otherwise.
async function planUsage($: Engine, rateLimits: SessionRateLimit[]): Promise<PlanUsage> {
  const session = rateLimits.find(limit => limit.kind === SESSION_WINDOW)?.percentUsed
  const weekly = rateLimits.find(limit => limit.kind === WEEKLY_WINDOW)?.percentUsed
  hasLivePlanUsage = session !== undefined && weekly !== undefined
  if (hasLivePlanUsage) {
    return { sessionPercent: session, weeklyPercent: weekly }
  }

  const fromFile = await planUsageFromFile($)

  return { sessionPercent: session ?? fromFile.sessionPercent, weeklyPercent: weekly ?? fromFile.weeklyPercent }
}

async function record($: Engine, context: SessionContextUsage, rateLimits: SessionRateLimit[]) {
  const current: UsageReading = { ...(await planUsage($, rateLimits)), contextPercent: await contextPercent($, context) }
  await update($, reading, () => current)
}

// Between turns only the plan usage file can move.
async function refreshPlanUsage($: Engine) {
  if (hasLivePlanUsage) {
    return
  }

  const fromFile = await planUsageFromFile($)
  await update($, reading, previous => ({ ...previous, ...fromFile }))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    $.clock.every(REFRESH_MS, () => void refreshPlanUsage($))

    const usage = await $.session.usage()
    await record($, usage.context, usage.rateLimits)

    return result
  })

  on('session.measure', async ($, e, next) => {
    await record($, e.context, e.rateLimits)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const current = await read($, reading)
    if (e.props.hasSurvey || current === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)

    return (
      <Box>
        <Text dimColor>
          <Text color={warnAt(current.sessionPercent, PLAN_WARN_PERCENT)}>Session tokens {percent(current.sessionPercent)}</Text>
          {', '}
          <Text color={warnAt(current.weeklyPercent, PLAN_WARN_PERCENT)}>weekly tokens {percent(current.weeklyPercent)}</Text>
          {', '}
          <Text color={warnAt(current.contextPercent, CONTEXT_WARN_PERCENT)}>context {percent(current.contextPercent)}</Text>
        </Text>
      </Box>
    )
  })
}

function percent(value: number | undefined) {
  return value === undefined ? '–' : `${value}%`
}

function warnAt(value: number | undefined, threshold: number) {
  return value !== undefined && value >= threshold ? 'warning' : undefined
}

