// What the band shows, each 0 to 100 and absent while unknown.
export type UsageReading = {
  // How much of the plan's 5-hour session allowance is used.
  sessionPercent?: number
  // How much of the plan's weekly allowance is used.
  weeklyPercent?: number
  // How far the context is towards auto-compaction, which runs at 100 (of the whole window when auto-compaction is off).
  contextPercent?: number
}

declare module 'claude-code' {
  interface PluginState {
    'usage-band': { reading: UsageReading | null }
  }
}
